using System.Reflection;using System.Text.Json;using System.Text.Json.Nodes;
namespace RisingLands;
public static class TradeV113Tests {
 public static void Run(string root,string output){int checks=0;void Check(bool ok,string label){if(!ok)throw new Exception(label);checks++;Console.WriteLine("PASS "+label);}void Until(Simulation s,Func<bool> done){for(int i=0;i<20000&&!done();i++)s.Step();Check(done(),"arrival/settlement completed");s.Step();s.Step();}
 var s=TradeV97Tests.Fixture(root);var home=s.World.Buildings.First(b=>b.Owner==0&&b.Type==2);var bag=s.Exchange(0)!;var colono=s.ReleaseResident(home.Slot)!;int count=s.Occupants(bag.Slot);Check(!Simulation.UnitExchangeable(9)&&!s.TradeUnits(0).Contains(colono),"colonist absent from trade lists");Check(!s.CanStoreTradeUnit(colono,bag),"colonist cannot use troop storage");Check(s.StoreTradeUnit(colono,bag),"colonist command redirects to occupation");Until(s,()=>colono.LegacyState==14);Check(s.Occupants(bag.Slot)==count+1&&!s.ExchangeOccupants(bag.Slot).Contains(colono)&&!s.Special.ExchangeResidents.Any(r=>r.Slot==colono.Slot),"colonist operates Exchange and is never cargo");
 var copy=TradeV97Tests.Fixture(root);copy.Restore(s.Serialize());Check(copy.Serialize()==s.Serialize(),"occupation save/load");
 var old=JsonNode.Parse(s.Serialize())!;old["Version"]=38;var actor=old["Units"]!.AsArray().First(x=>x!["Slot"]!.GetValue<int>()==colono.Slot)!;actor["LegacyState"]=12;old["Residents"]![bag.Slot.ToString()]!.AsArray().RemoveAt(old["Residents"]![bag.Slot.ToString()]!.AsArray().ToList().FindIndex(x=>x!.GetValue<int>()==colono.Slot));old["Special"]!["ExchangeResidents"]!.AsArray().Add(JsonSerializer.SerializeToNode(new ExchangeResident{Slot=colono.Slot,Building=bag.Slot,Cell=s.BuildingInteractionCells(bag).First(),Stored=true}));copy=TradeV97Tests.Fixture(root);copy.Restore(old.ToJsonString());Check(copy.Occupants(bag.Slot)==count+1&&!copy.ExchangeOccupants(bag.Slot).Any(a=>a.Type==9),"legacy stored colonist becomes operator");var normalized=copy.Serialize();var copy2=TradeV97Tests.Fixture(root);copy2.Restore(normalized);Check(copy2.Serialize()==normalized,"migrated operator deterministic roundtrip");
 s=TradeV97Tests.Fixture(root);s.Campaign.Goodwill[1]=0;s.Campaign.Alliances[1]=false;foreach(var data in new[]{(10,8,0),(20,8,1),(100,50,6),(10,0,1)}){var n=new Negotiation{Owner=1,Give=new[]{data.Item1,0,0},Take=new[]{0,data.Item2,0}};Check(s.TradeGoodwillGain(n)==data.Item3,"native surplus delta "+data.Item1+"/"+data.Item2);}
 var messenger=SpecialV66Tests.Recruit(s,10);var market=s.World.Buildings.First(b=>b.Owner==1&&b.Type==16);s.SendMessenger(messenger,market.Slot);Until(s,()=>s.NegotiationFor(1)?.Stage=="Ready");var session=s.NegotiationFor(1)!;var free=s.ReleaseResident(s.World.Buildings.First(b=>b.Owner==0&&b.Type==2).Slot)!;Check(!s.SubmitTrade(session,new[]{100,0,0},new[]{0,50,0},new[]{free.Slot}),"proposal rejects colonist explicitly");Check(s.SubmitTrade(session,new[]{100,0,0},new[]{0,50,0}),"favourable resource offer submitted");Check(s.Goodwill(1)==0,"proposal does not change sympathy");Until(s,()=>session.Stage=="Completed");Check(s.Goodwill(1)==6,"completed profitable trade raises sympathy by native amount");for(int i=0;i<300;i++)s.Step();Check(s.Goodwill(1)==6,"gain applied only once");copy=TradeV97Tests.Fixture(root);copy.Restore(s.Serialize());Check(copy.Goodwill(1)==6&&copy.Serialize()==s.Serialize(),"trade sympathy persists");
 Check(Simulation.UnitExchangeable(0)&&Simulation.UnitExchangeable(5)&&Simulation.UnitExchangeable(7)&&Simulation.UnitExchangeable(16),"other unit classes still tradeable");
 File.WriteAllText(output,JsonSerializer.Serialize(new{Checks=checks,Passed=true}));
 }
}

